'use strict';

// parse() and createParser() drive the same incremental Tokenizer, so input
// split into chunks at any point yields exactly what parse() yields for the
// whole text, errors and error positions included.

const QUOTE = 0x22;
const CR = 0x0d;
const LF = 0x0a;
const SPACE = 0x20;
const BOM = 0xfeff;

const DEFAULT_DELIMITER = ',';
const DEFAULT_EOL = '\r\n';
const ALLOWED_EOLS = ['\r\n', '\n'];

// Tokenizer states.
const FIELD_START = 0;
const UNQUOTED = 1;
const QUOTED = 2;
// A `"` was just read inside a quoted field. The next character decides
// whether it was the first half of `""` or the closing quote.
const AFTER_QUOTE = 3;

/**
 * Thrown for malformed CSV input. `line` and `column` are 1-based; columns
 * count UTF-16 code units.
 */
class CsvError extends Error {
  constructor(message, line, column) {
    super(`${message} (line ${line}, column ${column})`);
    this.name = 'CsvError';
    this.line = line;
    this.column = column;
  }
}

function describe(value) {
  if (value === null) return 'null';
  if (Array.isArray(value)) return 'an array';
  if (typeof value === 'string') return `the string ${JSON.stringify(value)}`;
  return `a value of type ${typeof value}`;
}

function checkOptions(options, caller) {
  if (options === null || typeof options !== 'object') {
    throw new TypeError(`${caller}: options must be an object, received ${describe(options)}`);
  }
}

function readDelimiter(delimiter, caller) {
  if (delimiter === undefined) return DEFAULT_DELIMITER;
  if (
    typeof delimiter !== 'string' ||
    delimiter.length !== 1 ||
    delimiter === '"' ||
    delimiter === '\r' ||
    delimiter === '\n'
  ) {
    throw new TypeError(
      `${caller}: options.delimiter must be a single character other than '"', CR or LF, received ${describe(delimiter)}`,
    );
  }
  return delimiter;
}

function readFlag(value, name, caller) {
  if (value === undefined) return false;
  if (typeof value !== 'boolean') {
    throw new TypeError(`${caller}: options.${name} must be a boolean, received ${describe(value)}`);
  }
  return value;
}

function toObject(columns, fields) {
  const record = {};
  for (let i = 0; i < columns.length; i++) {
    const key = columns[i];
    if (key === '__proto__') {
      // Plain assignment would call the prototype setter and drop the value.
      Object.defineProperty(record, key, { value: fields[i], writable: true, enumerable: true, configurable: true });
    } else {
      record[key] = fields[i];
    }
  }
  return record;
}

class Tokenizer {
  constructor(options, caller) {
    checkOptions(options, caller);
    this.delimiter = readDelimiter(options.delimiter, caller).charCodeAt(0);
    this.headerMode = readFlag(options.header, 'header', caller);
    this.skipEmptyLines = readFlag(options.skipEmptyLines, 'skipEmptyLines', caller);
    this.columns = null; // header names, once the header record has ended
    this.seenNames = this.headerMode ? new Set() : null; // non-null while reading the header record
    this.state = FIELD_START;
    this.started = false; // whether any input has arrived, for the leading BOM check
    this.pendingCR = false; // the previous character was CR, so an LF now completes a CRLF
    this.line = 1; // position of the next character
    this.column = 1;
    this.recordLine = 1;
    this.fieldLine = 1;
    this.fieldColumn = 1;
    this.parts = []; // pieces of the current field's value
    this.fields = []; // ended fields of the current record
    this.records = []; // ended records not yet handed out
  }

  write(chunk) {
    const n = chunk.length;
    const delimiter = this.delimiter;
    let i = 0;
    if (!this.started && n > 0) {
      this.started = true;
      if (chunk.charCodeAt(0) === BOM) i = 1;
    }
    while (i < n) {
      switch (this.state) {
        case FIELD_START: {
          const c = chunk.charCodeAt(i);
          if (this.pendingCR) {
            this.pendingCR = false;
            if (c === LF) {
              i++;
              continue;
            }
          }
          if (this.fields.length === 0) this.recordLine = this.line;
          this.fieldLine = this.line;
          this.fieldColumn = this.column;
          if (c === QUOTE) {
            this.state = QUOTED;
            this.column++;
            i++;
          } else if (c === delimiter) {
            this.endField('');
            this.column++;
            i++;
          } else if (c === CR || c === LF) {
            // A line break with no fields before it is an empty line.
            if (this.fields.length > 0 || !this.skipEmptyLines) {
              this.endField('');
              this.endRecord();
            }
            this.newLine(c);
            i++;
          } else {
            this.state = UNQUOTED;
          }
          break;
        }

        case UNQUOTED: {
          const start = i;
          let c = 0;
          while (i < n) {
            c = chunk.charCodeAt(i);
            if (c === delimiter || c === CR || c === LF) break;
            i++;
          }
          this.column += i - start;
          if (i === n) {
            if (i > start) this.parts.push(chunk.slice(start, i));
            break;
          }
          if (this.parts.length === 0) {
            this.endField(chunk.slice(start, i));
          } else {
            if (i > start) this.parts.push(chunk.slice(start, i));
            this.endField(this.takeValue());
          }
          i++;
          if (c === delimiter) {
            this.column++;
          } else {
            this.endRecord();
            this.newLine(c);
          }
          this.state = FIELD_START;
          break;
        }

        case QUOTED: {
          let line = this.line;
          let column = this.column;
          let pendingCR = this.pendingCR;
          const start = i;
          while (i < n) {
            const c = chunk.charCodeAt(i);
            if (c === QUOTE) break;
            if (c === CR) {
              line++;
              column = 1;
              pendingCR = true;
            } else if (c === LF) {
              if (!pendingCR) {
                line++;
                column = 1;
              }
              pendingCR = false;
            } else {
              column++;
              pendingCR = false;
            }
            i++;
          }
          if (i > start) this.parts.push(chunk.slice(start, i));
          if (i < n) {
            column++;
            i++;
            pendingCR = false;
            this.state = AFTER_QUOTE;
          }
          this.line = line;
          this.column = column;
          this.pendingCR = pendingCR;
          break;
        }

        case AFTER_QUOTE: {
          const c = chunk.charCodeAt(i);
          if (c === QUOTE) {
            this.parts.push('"');
            this.column++;
            this.state = QUOTED;
          } else if (c === delimiter) {
            this.endField(this.takeValue());
            this.column++;
            this.state = FIELD_START;
          } else if (c === CR || c === LF) {
            this.endField(this.takeValue());
            this.endRecord();
            this.newLine(c);
            this.state = FIELD_START;
          } else {
            throw new CsvError(
              `Unexpected character ${JSON.stringify(chunk[i])} after the closing quote of a field; expected a delimiter, a line break or the end of input`,
              this.line,
              this.column,
            );
          }
          i++;
          break;
        }
      }
    }
  }

  end() {
    switch (this.state) {
      case FIELD_START:
        // With no fields yet we are at the start of a record: either the input
        // is empty or it ended with a line break, and neither starts a record.
        if (this.fields.length > 0) {
          this.fieldLine = this.line;
          this.fieldColumn = this.column;
          this.endField('');
          this.endRecord();
        }
        break;
      case UNQUOTED:
      case AFTER_QUOTE:
        this.endField(this.takeValue());
        this.endRecord();
        break;
      case QUOTED:
        throw new CsvError('Quoted field is never closed', this.fieldLine, this.fieldColumn);
    }
  }

  takeRecords() {
    const records = this.records;
    this.records = [];
    return records;
  }

  takeValue() {
    const parts = this.parts;
    const value = parts.length === 1 ? parts[0] : parts.join('');
    parts.length = 0;
    return value;
  }

  newLine(c) {
    this.line++;
    this.column = 1;
    this.pendingCR = c === CR;
  }

  endField(value) {
    if (this.seenNames !== null) {
      if (this.seenNames.has(value)) {
        throw new CsvError(`Duplicate header name ${JSON.stringify(value)}`, this.fieldLine, this.fieldColumn);
      }
      this.seenNames.add(value);
    }
    this.fields.push(value);
  }

  endRecord() {
    const fields = this.fields;
    this.fields = [];
    if (!this.headerMode) {
      this.records.push(fields);
    } else if (this.columns === null) {
      this.columns = fields;
      this.seenNames = null;
    } else if (fields.length !== this.columns.length) {
      throw new CsvError(
        `Expected ${this.columns.length} fields to match the header but found ${fields.length}`,
        this.recordLine,
        1,
      );
    } else {
      this.records.push(toObject(this.columns, fields));
    }
  }
}

/**
 * Parses CSV text into an array of records: arrays of strings, or objects
 * keyed by the first record when `options.header` is true.
 *
 * @param {string} text
 * @param {{delimiter?: string, header?: boolean, skipEmptyLines?: boolean}} [options]
 * @returns {Array<string[]> | Array<Record<string, string>>}
 * @throws {TypeError} when `text` is not a string or an option is invalid.
 * @throws {CsvError} when the input is malformed.
 */
function parse(text, options = {}) {
  if (typeof text !== 'string') {
    throw new TypeError(`parse: text must be a string, received ${describe(text)}`);
  }
  const tokenizer = new Tokenizer(options, 'parse');
  tokenizer.write(text);
  tokenizer.end();
  return tokenizer.takeRecords();
}

/**
 * Creates a streaming parser with the same options as parse(). `write(chunk)`
 * returns the records whose ending line break is in `chunk`; `end()` returns
 * the rest. Once `end()` has been called or either method has thrown, both
 * methods throw.
 *
 * @param {{delimiter?: string, header?: boolean, skipEmptyLines?: boolean}} [options]
 * @returns {{write(chunk: string): Array<string[] | Record<string, string>>, end(): Array<string[] | Record<string, string>>}}
 */
function createParser(options = {}) {
  const tokenizer = new Tokenizer(options, 'createParser');
  let finished = false;

  function assertOpen(method) {
    if (finished) {
      throw new Error(`createParser: ${method}() called after the parser was ended or threw an error`);
    }
  }

  return {
    write(chunk) {
      assertOpen('write');
      try {
        if (typeof chunk !== 'string') {
          throw new TypeError(`createParser: write() chunk must be a string, received ${describe(chunk)}`);
        }
        tokenizer.write(chunk);
        return tokenizer.takeRecords();
      } catch (error) {
        finished = true;
        throw error;
      }
    },
    end() {
      assertOpen('end');
      finished = true;
      tokenizer.end();
      return tokenizer.takeRecords();
    },
  };
}

function readEol(eol) {
  if (eol === undefined) return DEFAULT_EOL;
  if (!ALLOWED_EOLS.includes(eol)) {
    throw new TypeError(`stringify: options.eol must be '\\r\\n' or '\\n', received ${describe(eol)}`);
  }
  return eol;
}

function readHeader(header) {
  if (header === undefined) return null;
  if (!Array.isArray(header)) {
    throw new TypeError(`stringify: options.header must be an array of column names, received ${describe(header)}`);
  }
  for (let i = 0; i < header.length; i++) {
    if (typeof header[i] !== 'string') {
      throw new TypeError(`stringify: options.header[${i}] must be a string, received ${describe(header[i])}`);
    }
  }
  return header;
}

function valueToText(value, rowIndex, fieldIndex) {
  if (typeof value === 'string') return value;
  if (typeof value === 'number' || typeof value === 'boolean') return String(value);
  if (value === null || value === undefined) return '';
  throw new TypeError(
    `stringify: value at row ${rowIndex}, field ${fieldIndex} must be a string, number, boolean, null or undefined, received ${describe(value)}`,
  );
}

function needsQuotes(text, delimiter) {
  const n = text.length;
  if (n === 0) return false;
  if (text.charCodeAt(0) === SPACE || text.charCodeAt(n - 1) === SPACE) return true;
  for (let i = 0; i < n; i++) {
    const c = text.charCodeAt(i);
    if (c === delimiter || c === QUOTE || c === CR || c === LF) return true;
  }
  return false;
}

function quote(text) {
  return `"${text.replaceAll('"', '""')}"`;
}

function formatRecord(values, delimiter, isFirstLine, rowIndex) {
  const delimiterCode = delimiter.charCodeAt(0);
  const texts = new Array(values.length);
  for (let i = 0; i < values.length; i++) {
    const text = valueToText(values[i], rowIndex, i);
    texts[i] = needsQuotes(text, delimiterCode) ? quote(text) : text;
  }
  // An empty line would parse as [''] or be dropped by skipEmptyLines.
  if (texts.length === 1 && texts[0] === '') return '""';
  let line = texts.join(delimiter);
  // parse() strips a leading BOM, so the first field must not expose one.
  if (isFirstLine && line.charCodeAt(0) === BOM) {
    texts[0] = quote(valueToText(values[0], rowIndex, 0));
    line = texts.join(delimiter);
  }
  return line;
}

/**
 * Serializes records to CSV text. Each record is an array of values, or an
 * object when `options.header` lists the column names; the header row is then
 * written first. Every record, the last included, ends with `options.eol`.
 *
 * @param {Array<unknown[] | Record<string, unknown>>} rows
 * @param {{delimiter?: string, eol?: '\r\n' | '\n', header?: string[]}} [options]
 * @returns {string}
 * @throws {TypeError} for invalid rows, values or options.
 */
function stringify(rows, options = {}) {
  checkOptions(options, 'stringify');
  const delimiter = readDelimiter(options.delimiter, 'stringify');
  const eol = readEol(options.eol);
  const header = readHeader(options.header);
  if (!Array.isArray(rows)) {
    throw new TypeError(`stringify: rows must be an array, received ${describe(rows)}`);
  }

  const lines = [];
  if (header !== null) lines.push(formatRecord(header, delimiter, true, 'header'));
  for (let r = 0; r < rows.length; r++) {
    const row = rows[r];
    let values;
    if (Array.isArray(row)) {
      values = row;
    } else if (header !== null && row !== null && typeof row === 'object') {
      values = header.map((key) => (Object.hasOwn(row, key) ? row[key] : undefined));
    } else {
      const expected = header === null ? 'an array' : 'an array or an object';
      throw new TypeError(`stringify: row ${r} must be ${expected}, received ${describe(row)}`);
    }
    lines.push(formatRecord(values, delimiter, lines.length === 0, r));
  }
  return lines.length === 0 ? '' : lines.join(eol) + eol;
}

module.exports = { parse, createParser, stringify, CsvError };

