          const start = i;
          let c = 0;
          while (i < n) {
            c = chunk.charCodeAt(i);
            if (c === delimiter || c === CR || c === LF) break;
            i++;
          }
          this.column += i - start;
          if (i === n) {
            if (i > start) this.parts.push(chunk.slice(start, i));
            break;
          }
          if (this.parts.length === 0) {
            this.endField(chunk.slice(start, i));
          } else {
