    const records = this.records;
    this.records = [];
    return records;
  }

  takeValue() {
    const parts = this.parts;
    const value = parts.length === 1 ? parts[0] : parts.join('');
    parts.length = 0;
    return value;
  }

  newLine(c) {
    this.line++;
    this.column = 1;
    this.pendingCR = c === CR;
