    this.seenNames = this.headerMode ? new Set() : null; // non-null while reading the header record
    this.state = FIELD_START;
    this.started = false; // whether any input has arrived, for the leading BOM check
    this.pendingCR = false; // the previous character was CR, so an LF now completes a CRLF
    this.line = 1; // position of the next character
    this.column = 1;
    this.recordLine = 1;
    this.fieldLine = 1;
    this.fieldColumn = 1;
    this.parts = []; // pieces of the current field's value
    this.fields = []; // ended fields of the current record
    this.records = []; // ended records not yet handed out
  }

  write(chunk) {
    const n = chunk.length;
    const delimiter = this.delimiter;
    let i = 0;
    if (!this.started && n > 0) {
      this.started = true;
      if (chunk.charCodeAt(0) === BOM) i = 1;
    }
    while (i < n) {
      switch (this.state) {
        case FIELD_START: {
          const c = chunk.charCodeAt(i);
          if (this.pendingCR) {
            this.pendingCR = false;
            if (c === LF) {
