            this.newLine(c);
          }
          this.state = FIELD_START;
          break;
        }

        case QUOTED: {
          let line = this.line;
          let column = this.column;
          let pendingCR = this.pendingCR;
          const start = i;
          while (i < n) {
            const c = chunk.charCodeAt(i);
            if (c === QUOTE) break;
            if (c === CR) {
              line++;
              column = 1;
              pendingCR = true;
            } else if (c === LF) {
              if (!pendingCR) {
                line++;
                column = 1;
              }
              pendingCR = false;
            } else {
              column++;
              pendingCR = false;
            }
            i++;
          }
          if (i > start) this.parts.push(chunk.slice(start, i));
          if (i < n) {
            column++;
            i++;
