            this.parts.push('"');
            this.column++;
            this.state = QUOTED;
          } else if (c === delimiter) {
            this.endField(this.takeValue());
            this.column++;
            this.state = FIELD_START;
          } else if (c === CR || c === LF) {
            this.endField(this.takeValue());
            this.endRecord();
            this.newLine(c);
            this.state = FIELD_START;
          } else {
            throw new CsvError(
              `Unexpected character ${JSON.stringify(chunk[i])} after the closing quote of a field; expected a delimiter, a line break or the end of input`,
              this.line,
              this.column,
            );
          }
          i++;
          break;
        }
      }
    }
  }

  end() {
    switch (this.state) {
      case FIELD_START:
        // With no fields yet we are at the start of a record: either the input
        // is empty or it ended with a line break, and neither starts a record.
        if (this.fields.length > 0) {
          this.fieldLine = this.line;
          this.fieldColumn = this.column;
          this.endField('');
          this.endRecord();
        }
        break;
      case UNQUOTED:
      case AFTER_QUOTE:
        this.endField(this.takeValue());
        this.endRecord();
        break;
      case QUOTED:
        throw new CsvError('Quoted field is never closed', this.fieldLine, this.fieldColumn);
    }
  }

  takeRecords() {
    const records = this.records;
    this.records = [];
    return records;
  }

  takeValue() {
    const parts = this.parts;
    const value = parts.length === 1 ? parts[0] : parts.join('');
    parts.length = 0;
    return value;
  }

  newLine(c) {
    this.line++;
    this.column = 1;
    this.pendingCR = c === CR;
  }

  endField(value) {
    if (this.seenNames !== null) {
      if (this.seenNames.has(value)) {
        throw new CsvError(`Duplicate header name ${JSON.stringify(value)}`, this.fieldLine, this.fieldColumn);
      }
