    }
    this.fields.push(value);
  }

  endRecord() {
    const fields = this.fields;
    this.fields = [];
    if (!this.headerMode) {
      this.records.push(fields);
    } else if (this.columns === null) {
      this.columns = fields;
      this.seenNames = null;
    } else if (fields.length !== this.columns.length) {
      throw new CsvError(
        `Expected ${this.columns.length} fields to match the header but found ${fields.length}`,
        this.recordLine,
        1,
      );
    } else {
      this.records.push(toObject(this.columns, fields));
    }
  }
}

