'use strict';

const { parse, createParser, CsvError } = require('../src/csv.js');

// Runs fn and reduces the result to something deepStrictEqual can compare:
// the records, or the thrown CsvError's position.
function outcome(fn) {
  try {
    return { records: fn() };
  } catch (error) {
    if (!(error instanceof CsvError)) throw error;
    return { error: { line: error.line, column: error.column } };
  }
}

function parseOutcome(text, options) {
  return outcome(() => parse(text, options));
}

// Feeds chunks to a fresh streaming parser and concatenates everything it returns.
function streamOutcome(chunks, options) {
  return outcome(() => {
    const parser = createParser(options);
    const records = [];
    for (const chunk of chunks) records.push(...parser.write(chunk));
    records.push(...parser.end());
    return records;
  });
}

function splitAt(text, points) {
  const chunks = [];
  let previous = 0;
  for (const point of points) {
    chunks.push(text.slice(previous, point));
    previous = point;
  }
  chunks.push(text.slice(previous));
  return chunks;
}

// mulberry32: a small seeded PRNG so randomized tests are reproducible.
function makeRandom(seed) {
  let state = seed >>> 0;
  const next = () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
  return {
    next,
    int: (max) => Math.floor(next() * max),
    pick: (items) => items[Math.floor(next() * items.length)],
  };
}

function randomChunks(text, random) {
  const points = [];
  for (let i = 1; i < text.length; i++) if (random.next() < 0.3) points.push(i);
  return splitAt(text, points);
}

function randomText(random, alphabet, maxLength) {
  const length = random.int(maxLength + 1);
  let text = '';
  for (let i = 0; i < length; i++) text += random.pick(alphabet);
  return text;
}

module.exports = { outcome, parseOutcome, streamOutcome, splitAt, makeRandom, randomChunks, randomText };

