      assert.throws(() => parse(text), TypeError);
    }
  });

  it('returns [] for an empty string', () => {
    assert.deepEqual(parse(''), []);
    assert.deepEqual(parse('', { header: true, skipEmptyLines: true }), []);
  });

  it('rejects a delimiter that is not one character other than a quote, CR or LF', () => {
    for (const delimiter of ['', ';;', '"', '\r', '\n', '\r\n', '😀', 1, null, [',']]) {
      assert.throws(() => parse('a', { delimiter }), TypeError, `delimiter ${JSON.stringify(delimiter)}`);
    }
  });

  it('rejects options that are not an object, and non-boolean flags', () => {
    assert.throws(() => parse('a', null), TypeError);
    assert.throws(() => parse('a', 'header'), TypeError);
    assert.throws(() => parse('a', { header: 'yes' }), TypeError);
    assert.throws(() => parse('a', { header: 1 }), TypeError);
    assert.throws(() => parse('a', { skipEmptyLines: 'true' }), TypeError);
  });

  it('ignores options it does not know, such as stringify-only ones', () => {
    assert.deepEqual(parse('a\n', { eol: '\n' }), [['a']]);
  });
});

describe('parse: records and fields', () => {
  it('splits fields on commas by default', () => {
    assert.deepEqual(parse('a,b,c\n1,2,3'), [
      ['a', 'b', 'c'],
      ['1', '2', '3'],
    ]);
  });

  it('uses a custom delimiter and treats commas as ordinary characters', () => {
    assert.deepEqual(parse('a;b,c\n"x;y";z', { delimiter: ';' }), [
      ['a', 'b,c'],
      ['x;y', 'z'],
    ]);
    assert.deepEqual(parse('a\tb', { delimiter: '\t' }), [['a', 'b']]);
  });

  it('accepts CRLF, LF and CR record separators mixed in one input', () => {
    assert.deepEqual(parse('a\r\nb\nc\rd'), [['a'], ['b'], ['c'], ['d']]);
  });

  it('treats LF followed by CR as two line breaks', () => {
    assert.deepEqual(parse('a\n\rb'), [['a'], [''], ['b']]);
  });

  it('keeps whitespace exactly', () => {
    assert.deepEqual(parse(' a , b \t\n  '), [[' a ', ' b \t'], ['  ']]);
  });

  it('keeps empty fields, including a trailing one', () => {
    assert.deepEqual(parse('a,,b\n,\na,\n'), [['a', '', 'b'], ['', ''], ['a', '']]);
  });

  it('passes non-ASCII text through unchanged', () => {
    assert.deepEqual(parse('é,日本,😀'), [['é', '日本', '😀']]);
  });
