describe('parse: byte order mark', () => {
  it('ignores a leading BOM', () => {
    assert.deepEqual(parse('\uFEFFa,b'), [['a', 'b']]);
    assert.deepEqual(parse('\uFEFF'), []);
    assert.deepEqual(parse('\uFEFFid\n1', { header: true }), [{ id: '1' }]);
  });

  it('keeps a BOM that is not the first character of the input', () => {
    assert.deepEqual(parse('a,\uFEFFb'), [['a', '\uFEFFb']]);
    assert.deepEqual(parse('\uFEFF\uFEFFa'), [['\uFEFFa']]);
  });

  it('counts columns from the first character after the BOM', () => {
    assertCsvError(() => parse('\uFEFF"a'), 1, 1);
    assertCsvError(() => parse('\uFEFF"a"x'), 1, 4);
  });
});

describe('parse: quoted fields', () => {
  it('keeps delimiters and line breaks inside quotes literally', () => {
    assert.deepEqual(parse('"a,b","c\nd","e\r\nf","g\rh"'), [['a,b', 'c\nd', 'e\r\nf', 'g\rh']]);
  });

  it('reads "" inside a quoted field as one quote', () => {
    assert.deepEqual(parse('"a""b",""""'), [['a"b', '"']]);
  });

  it('reads an empty quoted field as an empty string', () => {
    assert.deepEqual(parse('"",x\n""'), [['', 'x'], ['']]);
  });

  it('ends a quoted field at a delimiter, a line break or the end of input', () => {
    assert.deepEqual(parse('"a","b"\r\n"c"\r"d"\n"e"'), [['a', 'b'], ['c'], ['d'], ['e']]);
  });

  it('treats a quote that does not start a field as an ordinary character', () => {
    assert.deepEqual(parse('a"b,c"",d"'), [['a"b', 'c""', 'd"']]);
    assert.deepEqual(parse(' "a",b'), [[' "a"', 'b']]);
  });

  it('rejects a character after the closing quote at that character', () => {
    assertCsvError(() => parse('"ab"c'), 1, 5, /line 1, column 5/);
    assertCsvError(() => parse('x,"a" ,b'), 1, 6);
    assertCsvError(() => parse('x\n"a\nb"c'), 3, 3);
  });

  it('reports a quoted field that is never closed at its opening quote', () => {
    assertCsvError(() => parse('a,"bc'), 1, 3, /never closed/);
    assertCsvError(() => parse('a\nb,"c\nd'), 2, 3);
    // The final `""` is an escaped quote, so the field is still open.
    assertCsvError(() => parse('"a""'), 1, 1);
  });

  it('counts a CRLF inside quotes as one line break and LF CR as two', () => {
    assertCsvError(() => parse('"\r\n"x'), 2, 2);
    assertCsvError(() => parse('"\n\r"x'), 3, 2);
  });

  it('counts columns in UTF-16 code units', () => {
    // The emoji is two code units, so the stray x is at column 7.
    assertCsvError(() => parse('😀,"a"x'), 1, 7);
  });
