describe('parse: empty lines', () => {
  it('does not start a record after a final line break', () => {
    for (const text of ['a\n', 'a\r\n', 'a\r']) assert.deepEqual(parse(text), [['a']]);
  });

  it('turns every other empty line into a record with one empty field', () => {
    assert.deepEqual(parse('a\n\nb'), [['a'], [''], ['b']]);
    assert.deepEqual(parse('a\n\n'), [['a'], ['']]);
    assert.deepEqual(parse('\n'), [['']]);
    assert.deepEqual(parse('\r\n\r\n'), [[''], ['']]);
  });

  it('drops empty lines with skipEmptyLines', () => {
    assert.deepEqual(parse('a\n\n\r\n\rb\n\n', { skipEmptyLines: true }), [['a'], ['b']]);
    assert.deepEqual(parse('\n', { skipEmptyLines: true }), []);
  });

  it('keeps lines that only look empty with skipEmptyLines', () => {
    assert.deepEqual(parse('""\n \n,', { skipEmptyLines: true }), [[''], [' '], ['', '']]);
  });

  it('still counts skipped lines for error positions', () => {
    assertCsvError(() => parse('a\n\n\n"b', { skipEmptyLines: true }), 4, 1);
  });
});

describe('parse: header mode', () => {
  it('returns plain objects keyed by the header', () => {
    assert.deepEqual(parse('name,age\r\nAda,36\r\nAlan,41\r\n', { header: true }), [
      { name: 'Ada', age: '36' },
      { name: 'Alan', age: '41' },
    ]);
  });

  it('returns [] for an input that is only a header', () => {
    for (const text of ['a,b', 'a,b\n', 'a,b\r\n']) assert.deepEqual(parse(text, { header: true }), []);
  });

  it('works with a custom delimiter', () => {
    assert.deepEqual(parse('a;b\n1;2,3', { header: true, delimiter: ';' }), [{ a: '1', b: '2,3' }]);
  });

  it('reports a duplicate name where the second occurrence starts', () => {
    assertCsvError(() => parse('a,b,a\n1,2,3', { header: true }), 1, 5, /Duplicate header name "a"/);
    assertCsvError(() => parse('a,"a"', { header: true }), 1, 3);
    // The second empty name starts after the last delimiter, at the end of input.
    assertCsvError(() => parse('x,,', { header: true }), 1, 4);
    assertCsvError(() => parse('a,"x\ny",a', { header: true }), 2, 4);
  });

  it('allows repeated values in data records', () => {
    assert.deepEqual(parse('a,b\n1,1', { header: true }), [{ a: '1', b: '1' }]);
  });

  it('rejects a record with more or fewer fields than the header at its first line, column 1', () => {
    assertCsvError(() => parse('a,b\n1,2\n1,2,3', { header: true }), 3, 1, /Expected 2 fields .* found 3/);
    assertCsvError(() => parse('a,b\n1', { header: true }), 2, 1);
    assertCsvError(() => parse('a,b\n"x\ny",1\n2', { header: true }), 4, 1);
    assertCsvError(() => parse('a,b\n"x\ny"', { header: true }), 2, 1);
  });

  it('treats an empty line as a one-field record unless skipEmptyLines is set', () => {
    assertCsvError(() => parse('a,b\n\n1,2', { header: true }), 2, 1);
    assert.deepEqual(parse('a\n\nx', { header: true }), [{ a: '' }, { a: 'x' }]);
    assert.deepEqual(parse('\n\na,b\n\n1,2\n\n', { header: true, skipEmptyLines: true }), [{ a: '1', b: '2' }]);
  });

  it('stores a __proto__ column as an own property', () => {
    const [record] = parse('__proto__,x\n1,2', { header: true });
    assert.equal(Object.getPrototypeOf(record), Object.prototype);
    assert.ok(Object.hasOwn(record, '__proto__'));
    assert.deepEqual(Object.entries(record), [
      ['__proto__', '1'],
      ['x', '2'],
    ]);
  });
});

describe('parse: several errors in one input', () => {
  it('throws the error a left-to-right read reaches first', () => {
    // The stray x comes before the record ends, so it wins over the field count.
    assertCsvError(() => parse('a,b\n1,2,"3"x', { header: true }), 2, 8);
    // The count is checked when record 2 ends, before the unclosed quote.
    assertCsvError(() => parse('a,b\n1\n"x', { header: true }), 2, 1);
    // A duplicate is known when its field ends, before the stray y.
    assertCsvError(() => parse('a,a,"b"y', { header: true }), 1, 3);
    // An unclosed quote means the record never ends, so its count is never checked.
    assertCsvError(() => parse('a,b\n1,2,"3', { header: true }), 2, 5);
    assertCsvError(() => parse('"a"x,"b"y'), 1, 4);
  });
});

describe('CsvError', () => {
  it('is an Error subclass with a position in its properties and message', () => {
    const error = outcome(() => parse('ok\n"bad')).error;
    assert.deepEqual(error, { line: 2, column: 1 });
    assert.throws(
      () => parse('ok\n"bad'),
      (thrown) =>
        thrown instanceof Error &&
        thrown instanceof CsvError &&
        thrown.name === 'CsvError' &&
        /line 2, column 1/.test(thrown.message),
    );
  });

  it('can be constructed directly', () => {
    const error = new CsvError('custom', 3, 7);
    assert.equal(error.line, 3);
    assert.equal(error.column, 7);
    assert.match(error.message, /^custom/);
  });
});

// An index-based reading of the spec over the whole string, written
// separately from the tokenizer, used as an oracle for random inputs.
function referenceParse(input, { delimiter = ',', header = false, skipEmptyLines = false } = {}) {
  const text = input.startsWith('\uFEFF') ? input.slice(1) : input;
  const n = text.length;
  const lineAt = [];
  const columnAt = [];
  let line = 1;
  let column = 1;
  for (let i = 0; i <= n; i++) {
    lineAt.push(line);
    columnAt.push(column);
    if (text[i] === '\r' || (text[i] === '\n' && text[i - 1] !== '\r')) {
      line++;
      column = 1;
    } else if (text[i] !== '\n') {
      column++;
    }
  }
  const fail = (index) => {
    throw new CsvError('reference', lineAt[index], columnAt[index]);
  };
  const isBreak = (i) => text[i] === '\r' || text[i] === '\n';
  const afterBreak = (i) => (text[i] === '\r' && text[i + 1] === '\n' ? i + 2 : i + 1);

  const records = [];
  let columns = null;
  const emit = (fields, start) => {
    if (!header) records.push(fields);
    else if (columns === null) columns = fields;
    else if (fields.length !== columns.length) throw new CsvError('reference', lineAt[start], 1);
    else records.push(Object.fromEntries(columns.map((name, k) => [name, fields[k]])));
  };

  let i = 0;
  while (i < n) {
    const start = i;
    if (isBreak(i)) {
      i = afterBreak(i);
      if (!skipEmptyLines) emit([''], start);
      continue;
    }
    const fields = [];
    const seen = header && columns === null ? new Set() : null;
    for (;;) {
      const fieldStart = i;
      let value = '';
      if (text[i] === '"') {
        let j = i + 1;
        for (;;) {
          if (j >= n) fail(fieldStart);
          if (text[j] !== '"') {
            value += text[j++];
          } else if (text[j + 1] === '"') {
            value += '"';
            j += 2;
          } else {
            j++;
            break;
          }
        }
        if (j < n && text[j] !== delimiter && !isBreak(j)) fail(j);
        i = j;
      } else {
        let j = i;
        while (j < n && text[j] !== delimiter && !isBreak(j)) j++;
        value = text.slice(i, j);
        i = j;
      }
      if (seen) {
        if (seen.has(value)) fail(fieldStart);
        seen.add(value);
      }
      fields.push(value);
      if (i < n && text[i] === delimiter) {
        i++;
        continue;
      }
      break;
    }
    if (i < n) i = afterBreak(i);
    emit(fields, start);
  }
  return records;
}

describe('parse: agreement with a reference reading of the spec', () => {
  const alphabet = ['a', 'b', ',', ';', '"', '"', '"', '\r', '\n', ' ', '\uFEFF', '😀'];
  const optionSets = [
    {},
    { skipEmptyLines: true },
    { header: true },
    { header: true, skipEmptyLines: true },
    { delimiter: ';' },
    { delimiter: ';', header: true },
  ];

  for (const options of optionSets) {
    it(`matches on random inputs with ${JSON.stringify(options)}`, () => {
      const random = makeRandom(0xc5f + optionSets.indexOf(options));
      for (let run = 0; run < 3000; run++) {
        const text = randomText(random, alphabet, 14);
        assert.deepEqual(
          parseOutcome(text, options),
          outcome(() => referenceParse(text, options)),
          `input ${JSON.stringify(text)}`,
        );
      }
    });
  }
});

