  const alphabet = ['a', 'b', ',', ';', '"', '"', '"', '\r', '\n', ' ', '﻿', '😀'];
  const optionSets = [
    {},
    { skipEmptyLines: true },
    { header: true },
    { header: true, skipEmptyLines: true },
    { delimiter: ';' },
    { delimiter: ';', header: true },
