  // which at this size takes far longer than the timeout.
  it('handles one-character chunks of many records', { timeout: 10_000 }, () => {
    const text = 'id,"quoted ""x""\r\nvalue",z\n'.repeat(10_000);
    const parser = createParser();
    let count = 0;
    for (let i = 0; i < text.length; i++) count += parser.write(text[i]).length;
