'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const { stringify } = require('../src/csv.js');

describe('stringify: records and values', () => {
  it('joins fields with commas and ends every record with CRLF', () => {
    assert.equal(
      stringify([
        ['a', 'b'],
        ['1', '2'],
      ]),
      'a,b\r\n1,2\r\n',
    );
  });

  it('returns an empty string for no rows', () => {
    assert.equal(stringify([]), '');
  });

  it('writes numbers and booleans with String() and null or undefined as empty fields', () => {
    assert.equal(stringify([[0, -1.5, NaN, 1e21, true, false, null, undefined]]), '0,-1.5,NaN,1e+21,true,false,,\r\n');
  });

  it('treats holes in a sparse record as empty fields', () => {
    // eslint-disable-next-line no-sparse-arrays
    assert.equal(stringify([['a', , 'c']]), 'a,,c\r\n');
  });

  it('throws TypeError for any other value type', () => {
    for (const value of [{}, ['a'], new Date(0), Symbol('s'), 10n, () => 'x', new String('a')]) {
      assert.throws(() => stringify([['ok', value]]), /row 0, field 1/, String(typeof value));
    }
  });

  it('writes a record with no fields as an empty line', () => {
    assert.equal(stringify([[], ['a']]), '\r\na\r\n');
  });
});

describe('stringify: quoting', () => {
  it('quotes a field containing the delimiter, a quote, CR or LF and doubles quotes', () => {
    assert.equal(stringify([['a,b', 'say "hi"', 'x\ry', 'x\ny', 'x\r\ny']]), '"a,b","say ""hi""","x\ry","x\ny","x\r\ny"\r\n');
  });

  it('quotes a field that begins or ends with a space', () => {
    assert.equal(stringify([[' a', 'b ', ' ', 'c d']]), '" a","b "," ",c d\r\n');
  });

  it('leaves other whitespace and plain text unquoted', () => {
    assert.equal(stringify([['\ta', 'b\t', 'é😀']]), '\ta,b\t,é😀\r\n');
  });

  it('writes a record whose single field is empty as ""', () => {
    assert.equal(stringify([[''], ['a'], [null], [undefined]]), '""\r\na\r\n""\r\n""\r\n');
  });

  it('does not quote empty fields in a record with several fields', () => {
    assert.equal(stringify([['', '']]), ',\r\n');
  });

  it('quotes the first field of the output when it would start with a BOM', () => {
    assert.equal(stringify([['﻿a', 'b'], ['﻿c']]), '"﻿a",b\r\n﻿c\r\n');
    assert.equal(stringify([['', 'a']], { delimiter: '﻿' }), '""﻿a\r\n');
  });
});

describe('stringify: options', () => {
  it('uses LF when eol is "\\n"', () => {
    assert.equal(stringify([['a'], ['b']], { eol: '\n' }), 'a\nb\n');
  });

  it('rejects any other eol', () => {
    for (const eol of ['\r', '', '\n\r', ';', null, 10]) {
      assert.throws(() => stringify([['a']], { eol }), TypeError, JSON.stringify(eol));
    }
  });

  it('uses a custom delimiter for joining and for quoting decisions', () => {
    assert.equal(stringify([['a,b', 'c;d']], { delimiter: ';' }), 'a,b;"c;d"\r\n');
    assert.equal(stringify([['a', 'b c']], { delimiter: ' ' }), 'a "b c"\r\n');
  });

  it('rejects delimiters as parse does', () => {
    for (const delimiter of ['', ';;', '"', '\r', '\n', 1, null]) {
      assert.throws(() => stringify([['a']], { delimiter }), TypeError, JSON.stringify(delimiter));
    }
  });

  it('rejects rows or options of the wrong type', () => {
    assert.throws(() => stringify('a,b'), TypeError);
    assert.throws(() => stringify(null), TypeError);
    assert.throws(() => stringify([['a']], null), TypeError);
    assert.throws(() => stringify(['a']), /row 0 must be an array/);
    assert.throws(() => stringify([{ a: 1 }]), /row 0 must be an array/);
  });

  it('ignores options it does not know, such as skipEmptyLines', () => {
    assert.equal(stringify([['a']], { skipEmptyLines: true }), 'a\r\n');
  });
});

describe('stringify: header', () => {
  const header = ['id', 'name'];

  it('writes the header row first and object values in header order', () => {
    assert.equal(
      stringify(
        [
          { name: 'Ada', id: 1 },
          { id: 2, name: 'Alan, T.' },
        ],
        { header },
      ),
      'id,name\r\n1,Ada\r\n2,"Alan, T."\r\n',
    );
  });

  it('writes a missing or inherited key as an empty field and ignores extra keys', () => {
    const inherited = Object.create({ name: 'from prototype' });
    inherited.id = 3;
    assert.equal(stringify([{ id: 1, extra: 'x' }, inherited], { header }), 'id,name\r\n1,\r\n3,\r\n');
    assert.equal(stringify([{}], { header: ['toString'] }), 'toString\r\n""\r\n');
  });

  it('still accepts array records', () => {
    assert.equal(stringify([['1', 'Ada'], { id: 2 }], { header }), 'id,name\r\n1,Ada\r\n2,\r\n');
  });

  it('writes only the header row when there are no rows', () => {
    assert.equal(stringify([], { header }), 'id,name\r\n');
  });

  it('quotes header names like any other field', () => {
    assert.equal(stringify([], { header: ['a b', ' c', 'd"e'] }), 'a b," c","d""e"\r\n');
    assert.equal(stringify([], { header: [''] }), '""\r\n');
  });

  it('rejects a header that is not an array of strings', () => {
    for (const bad of [true, 'id', {}, null, [1], ['a', null]]) {
      assert.throws(() => stringify([], { header: bad }), TypeError, JSON.stringify(bad));
    }
  });

  it('rejects null and non-object records', () => {
    assert.throws(() => stringify([null], { header }), /row 0 must be an array or an object/);
    assert.throws(() => stringify([{ id: 1 }, 'x'], { header }), /row 1 must be an array or an object/);
  });

  it('throws TypeError for an unsupported value in an object record', () => {
    assert.throws(() => stringify([{ id: 1, name: { first: 'Ada' } }], { header }), TypeError);
  });
});

describe('stringify: input is left unchanged', () => {
  it('does not modify the rows, the records or the header', () => {
    const header = ['a', 'b'];
    const rows = [{ a: 'x "y"', b: null }, ['1', 2, true], ['﻿']];
    const before = structuredClone({ header, rows });
    stringify(rows, { header, delimiter: ';', eol: '\n' });
    assert.deepEqual({ header, rows }, before);
  });
});

