'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const csv = require('../src/csv.js');
const { makeRandom, randomChunks, randomText, streamOutcome } = require('./helpers.js');

const { parse, stringify } = csv;

describe('round trip: parse(stringify(rows, opts), opts)', () => {
  const tricky = [
    [['']],
    [[''], [''], ['a']],
    [['', '']],
    [['﻿']],
    [['﻿a', 'b']],
    [[' '], ['"'], ['""'], ['\r'], ['\n'], ['a\r\nb']],
    [['a,b', 'x"y', ' lead', 'trail ']],
  ];

  it('returns the same rows for inputs that need quoting', () => {
    for (const rows of tricky) {
      for (const skipEmptyLines of [false, true]) {
        assert.deepEqual(parse(stringify(rows), { skipEmptyLines }), rows, JSON.stringify(rows));
      }
    }
  });

  it('returns the same rows for random rows and options', () => {
    const random = makeRandom(0xab1e);
    const alphabet = ['a', ' ', ',', ';', '\t', '"', '\r', '\n', '\r\n', '﻿', 'é', '😀'];
    const delimiters = [undefined, ',', ';', '\t', ' ', 'a', '﻿'];
    for (let run = 0; run < 3000; run++) {
      const rows = Array.from({ length: random.int(5) }, () =>
        Array.from({ length: 1 + random.int(4) }, () => randomText(random, alphabet, 5)),
      );
      const options = {
        delimiter: random.pick(delimiters),
        eol: random.pick([undefined, '\r\n', '\n']),
        skipEmptyLines: random.pick([undefined, false, true]),
      };
