/**
 * Parses CSV text into an array of records: arrays of strings, or objects
 * keyed by the first record when `options.header` is true.
 *
 * @param {string} text
 * @param {{delimiter?: string, header?: boolean, skipEmptyLines?: boolean}} [options]
 * @returns {Array<string[]> | Array<Record<string, string>>}
 * @throws {TypeError} when `text` is not a string or an option is invalid.
 * @throws {CsvError} when the input is malformed.
 */
function parse(text, options = {}) {
  if (typeof text !== 'string') {
    throw new TypeError(`parse: text must be a string, received ${describe(text)}`);
  }
  const tokenizer = new Tokenizer(options, 'parse');
  tokenizer.write(text);
  tokenizer.end();
  return tokenizer.takeRecords();
}

/**
 * Creates a streaming parser with the same options as parse(). `write(chunk)`
 * returns the records whose ending line break is in `chunk`; `end()` returns
 * the rest. Once `end()` has been called or either method has thrown, both
 * methods throw.
 *
 * @param {{delimiter?: string, header?: boolean, skipEmptyLines?: boolean}} [options]
 * @returns {{write(chunk: string): Array<string[] | Record<string, string>>, end(): Array<string[] | Record<string, string>>}}
 */
function createParser(options = {}) {
  const tokenizer = new Tokenizer(options, 'createParser');
  let finished = false;

  function assertOpen(method) {
    if (finished) {
      throw new Error(`createParser: ${method}() called after the parser was ended or threw an error`);
    }
  }

  return {
    write(chunk) {
      assertOpen('write');
      try {
        if (typeof chunk !== 'string') {
          throw new TypeError(`createParser: write() chunk must be a string, received ${describe(chunk)}`);
        }
        tokenizer.write(chunk);
        return tokenizer.takeRecords();
      } catch (error) {
        finished = true;
        throw error;
      }
    },
    end() {
      assertOpen('end');
      finished = true;
      tokenizer.end();
      return tokenizer.takeRecords();
    },
  };
}

function readEol(eol) {
  if (eol === undefined) return DEFAULT_EOL;
  if (!ALLOWED_EOLS.includes(eol)) {
    throw new TypeError(`stringify: options.eol must be '\\r\\n' or '\\n', received ${describe(eol)}`);
